float InverseLerp(float A, float B, float T)
{
    return (T - A)/(B - A);
}
float rand(float co) { return fract(sin(co*(91.3458)) * 47453.5453); }


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;


    //vec2 mouse = iMouse.xy/iResolution.xy;

    float timeSpeed = 0.5 * rand(1.); 

    float speed = 0.5;

    float fractAmount = 1.;

    vec2 overlayPos = vec2(.5);

    vec2 uvMix = vec2(cos(iTime * timeSpeed),sin(iTime * timeSpeed));



    float t = iTime * speed;

    //vec2 centerScale = vec2(0.5); //note that centerScale as a static value, gives a simple 'centered overlay.' given overlayPos = .5
    vec2 centerScale = vec2(fract(mix(cos(t), sin(t), uv.x * uvMix.x) * mix(sin(t), cos(t), uv.y * uvMix.y) * fractAmount));




    centerScale *= .5;

    vec2 centerXY = overlayPos;



    if(uv.x >= centerXY.x - centerScale.x && uv.x <= centerXY.x + centerScale.x
    && uv.y >= centerXY.y - centerScale.y && uv.y < centerXY.y + centerScale.y )
    {
        //x,y = 0 in normal scale = centerXY - centerScale = lowerbound.
        //x,y = 1 in normal scale = centerXY + centerScale = upperbound.

        vec2 upperbound = centerXY + centerScale;
        vec2 lowerbound = centerXY - centerScale;

        vec2 bounds = vec2( InverseLerp(lowerbound.x, upperbound.x, uv.x), InverseLerp(lowerbound.y, upperbound.y, uv.y));

        fragColor = texture(iChannel0, bounds);

    }
    else
    {
        fragColor = texture(iChannel0, uv);
    }
}
